import sys

def main():
    X = int(sys.stdin.read().split()[0])
    # Alturas conhecidas: mes 5 -> 7 caixinhas, mes 6 -> 13 caixinhas.
    # A partir do 6o mes, o crescimento mensal e fixo:
    # crescimento entre o 5o e o 6o mes = 13 - 7 = 6 caixinhas/mes.
    if X == 5:
        print(7)
    elif X == 6:
        print(13)
    else:
        print(13 + 6 * (X - 6))

